typedef float rational_t;
struct vector3d { float x, y, z; vector3d &operator=(const vector3d &v) { x=v.x; y=v.y; z=v.z; return *this; } };
struct po { char data[0x30]; vector3d position; const vector3d &get_position() const { return position; } };
class stringx { const char *text; public: const char *c_str() const { return text; } };
extern const vector3d ZEROVEC;
extern "C" char *strstr(const char *, const char *);
class particle_generator {
  char entity_before_abs_po[0x50]; po *abs_po; char entity_rest[0x1ac];
public:
  bool always_render; bool pad201, pad202, pad203; bool disable_for_sony_booth; char pad205[3];
  stringx filename; void *particles; int start_particle; int end_particle; int max_particles;
  rational_t particle_life_span, life_variation, birthrate, rate_variation, base_speed, speed_variation;
  rational_t spread_off_axis, spread_off_plane, scale_variation, grow_for, shrink_for, fade_out, fade_in;
  rational_t motion_inheritance, generation_radius, generation_height, rotation_period, recip_rotation_period;
  rational_t rotational_speed_variation, rotational_start_variation, on_for, off_for;
  unsigned int flags; rational_t time_to_next_particle, rh_grow_for, rh_shrink_for, rh_fade_in, rh_fade_out;
  char pad290[12]; vector3d abs_visual_center, visual_center; rational_t visual_radius; vector3d last_position; bool last_position_valid;
  const vector3d &get_abs_position() const { return abs_po->get_position(); }
  rational_t get_base_visual_radius() const;
  void initialize_variables();
};
__asm__(".equ get_base_visual_radius__C18particle_generator, 0x002D2D70");

void particle_generator::initialize_variables()
{
  disable_for_sony_booth = false;
  always_render = false;

  particles = 0;
  start_particle = 0;
  end_particle = 0;
  max_particles = 0;
  particle_life_span = 0.0f;
  life_variation = 0.5f;
  birthrate = 0;
  rate_variation = 0.8f;
  base_speed = 1.0f;
  speed_variation = 0.8f;
  spread_off_axis = 3.14159265358979323846f * 0.5f;
  time_to_next_particle = 0.0f;
  scale_variation = 0.5f;
  grow_for = 0.0f;
  shrink_for = 2.0f;
  fade_in = 0.0f;
  fade_out = 0.0f;
  spread_off_plane = 3.14159265358979323846f * 0.125f;
  motion_inheritance = 1.0f;
  generation_radius = 2.0f;
  generation_height = 2.0f;
  rotation_period = 0.0f;
  recip_rotation_period = 0.0f;
  rotational_speed_variation = 0.0f;
  rotational_start_variation = 0.0f;
  on_for = 1e25f;
  off_for = 0.0f;
  flags = 0;

  time_to_next_particle = 0.0f;

  rh_grow_for = 0.0f;
  rh_shrink_for = 0.0f;
  rh_fade_in = 0.0f;
  rh_fade_out = 0.0f;

  abs_visual_center = get_abs_position();
  visual_center = ZEROVEC;
  visual_radius = get_base_visual_radius();

  last_position = ZEROVEC;
  last_position_valid = false;

  if( strstr( filename.c_str(), "spraymsletrailsmoke" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraymsletrailglow" ) ) disable_for_sony_booth = false;
