  if( strstr( filename.c_str(), "spraygenexpsmrim" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpsmpreglow" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpsmpreline" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpsmressmoke" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpsmring" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpmdfirehead" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpmdfiretrail" ) ) disable_for_sony_booth = false;
  if( strstr( filename.c_str(), "spraygenexpmdflysmoke" ) ) disable_for_sony_booth = false;
